<?phpnamespace App\Http\Livewire;use App\Models\Attempt;use App\Models\Masturbation;use App\Models\Position;use Illuminate\Support\Facades\Auth;use Livewire\Component;class ActivityTracker extends Component{    public $filter_date_from;    public $filter_date_to;    public function mount()    {        $this->filter_date_from = now()->startOfMonth()->format('Y-m-d');        $this->filter_date_to = now()->endOfMonth()->format('Y-m-d');    }    public function getStatsProperty()    {        $attempts = Attempt::where('created_by', Auth::id())            ->whereBetween('attempt_date', [$this->filter_date_from, $this->filter_date_to])            ->get();        $masturbations = Masturbation::where('created_by', Auth::id())            ->whereBetween('entry_date', [$this->filter_date_from, $this->filter_date_to])            ->get();        $allPositionIds = $attempts            ->pluck('positions')            ->flatMap(function ($item) {                return is_array($item) ? $item : json_decode($item, true);            })            ->filter();        $topPositionName = 'N/A';        $topPositionImage = null;        if ($allPositionIds->isNotEmpty()) {            $positionCounts = $allPositionIds->countBy();            $topPositionId = $positionCounts->sortDesc()->keys()->first();            $topPosition = Position::find($topPositionId);            $topPositionName = $topPosition?->name ?? 'Unknown';            $topPositionImage = $topPosition?->photo ?? null;        }        return [            'total_sex_attempts' => $attempts->count(),            'total_masturbation_sessions' => $masturbations->sum('count'),            'top_position' => $topPositionName,            'top_position_image' => $topPositionImage,        ];    }    public function resetFilters()    {        $this->mount();    }    public function render()    {        return view('livewire.activity-tracker', [            'stats' => $this->stats,        ]);    }}